import{_ as t,o,c as a,a3 as d}from"./chunks/framework.r0uj6mzT.js";const p=JSON.parse('{"title":"Command-line reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md","lastUpdated":1793464624000}'),r={name:"reference/cli.md"};function n(i,e,c,s,l,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="command-line-reference" tabindex="-1">Command-line reference <a class="header-anchor" href="#command-line-reference" aria-label="Permalink to &quot;Command-line reference&quot;">​</a></h1><p>Run <code>boomerangz COMMAND --help</code> for the authoritative help installed with your version. Commands return exit status zero on success and one on failure; errors are written to standard error.</p><p>Commands that read configuration accept:</p><table tabindex="0"><thead><tr><th>Option</th><th>Default</th></tr></thead><tbody><tr><td><code>--config</code></td><td><code>/etc/boomerangz/config.toml</code></td></tr><tr><td><code>--config-dir</code></td><td><code>/etc/boomerangz/config.d</code></td></tr></tbody></table><h2 id="configuration-and-version" tabindex="-1">Configuration and version <a class="header-anchor" href="#configuration-and-version" aria-label="Permalink to &quot;Configuration and version&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>boomerangz config check</code></td><td>Validate the primary file, drop-ins, and merged configuration.</td></tr><tr><td><code>boomerangz config show</code></td><td>Print merged TOML with private-key fields redacted.</td></tr><tr><td><code>boomerangz config reload</code></td><td>Validate and atomically apply the running daemon configuration. Use <code>--socket PATH</code> to select a non-default current control socket. The JSON result lists the configuration generation, fields applied live, and fields requiring restart.</td></tr><tr><td><code>boomerangz version</code></td><td>Show build version, commit, and date.</td></tr><tr><td><code>boomerangz version --json</code></td><td>Emit version information as JSON.</td></tr></tbody></table><h2 id="daemon-and-operation" tabindex="-1">Daemon and operation <a class="header-anchor" href="#daemon-and-operation" aria-label="Permalink to &quot;Daemon and operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Options and arguments</th></tr></thead><tbody><tr><td><code>boomerangz daemon</code></td><td>Run management in the foreground.</td></tr><tr><td><code>boomerangz status</code></td><td><code>--credential NAME_OR_PATH</code>, <code>--watch</code>/<code>-w</code>, and <code>--json</code>.</td></tr><tr><td><code>boomerangz trigger [DATASET...]</code></td><td>Snapshot each named actor root&#39;s members now. Empty selects every active root; a member is refused with the root to use instead. <code>--credential NAME_OR_PATH</code> addresses a paired listener.</td></tr></tbody></table><p>Interactive status uses a readable terminal view; an interactive watch adds the most recent job state changes beneath it. Redirected one-shot output is one JSON object; redirected watch output is newline-delimited JSON. Add <code>--json</code> to emit that structured output even when standard output is a terminal. A watch sends an update whenever the daemon&#39;s status changes, and only then. Each watch object also carries <code>transitions</code>, every job state change since the previous object in the order the daemon recorded it. Each job entry names its run and what that run acted on, such as the snapshot a transfer sent, in the job identity fields. Status also reports each destination whose delegated ZFS permissions lack something Boomerangz may need, under <code>WARNINGS</code> in a terminal and in <code>destinations</code> in JSON. A watch that falls too far behind the daemon ends with an <code>Aborted</code> error and exits with status one rather than continuing with changes missing. See <a href="/operations/#view-status">View status</a> for the fields and the job states, and <a href="/operations/#job-identity">Job identity</a> for the identity fields, and <a href="/operations/#destination-permissions">Destination permissions</a> for the permission check.</p><h2 id="dataset-lifecycle" tabindex="-1">Dataset lifecycle <a class="header-anchor" href="#dataset-lifecycle" aria-label="Permalink to &quot;Dataset lifecycle&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Options and arguments</th></tr></thead><tbody><tr><td><code>boomerangz dataset list</code></td><td>Print a readable inventory with each dataset&#39;s management status: <code>active</code> for an actor root, <code>member</code> or <code>excluded</code> within a root, <code>target</code> for a replica received into, <code>inactive</code>, or <code>invalid</code>, with a root&#39;s blocked destinations beside it. Inactive datasets are hidden unless asked for; <code>--status STATUS</code> shows only datasets with that status, takes <code>all</code>, <code>active</code>, <code>member</code>, <code>excluded</code>, <code>target</code>, <code>inactive</code> or <code>invalid</code>, and can be repeated or given a comma-separated list, with <code>all</code> showing every dataset. Add <code>--json</code> for structured output, filtered the same way, which carries <code>covered_by</code> and <code>member</code> on datasets within a root, <code>members</code> and <code>blocked</code> on a root, and <code>replica</code> on a target.</td></tr><tr><td><code>boomerangz dataset inspect DATASET</code></td><td>Print readable effective policy, provenance, activation, the actor root it belongs to or a root&#39;s members, what marks it as a replica, blocked destinations with what each collides with, warnings, and errors for one exact dataset. Add <code>--json</code> for structured output.</td></tr><tr><td><code>boomerangz dataset adopt DATASET</code></td><td>Preview adoption of an actor root; <code>--apply</code> performs the revalidated plan. A member is refused with its root named.</td></tr><tr><td><code>boomerangz dataset reseed DATASET TARGET</code></td><td>Preview destruction and fresh seeding of one actor root&#39;s replica on a local destination root or named remote that the root or any member sends to, resetting every member on it; <code>--apply</code> performs the revalidated plan. A member, or a destination blocked by a collision, is refused.</td></tr><tr><td><code>boomerangz dataset abort-receive DATASET TARGET</code></td><td>Preview discarding the interrupted receives that a local destination root or named remote holds for one actor root and its members; <code>--apply</code> performs the revalidated plan. The replica, its snapshots, the binding and the source&#39;s replication history stay. A member, or a destination blocked by a collision, is refused.</td></tr><tr><td><code>boomerangz dataset clean [DATASET...]</code></td><td>Preview decommissioning. Use <code>--recursive</code>, <code>--all</code>, <code>--destroy-owned-snapshots</code>, <code>--forget-target TARGET</code>, and <code>--apply</code> as needed.</td></tr><tr><td><code>boomerangz identity recover</code></td><td>Preview recovery. <code>--owner UUID</code> resolves multiple candidates; <code>--apply</code> performs the revalidated plan.</td></tr><tr><td><code>boomerangz migrate [DATASET...]</code></td><td>Preview moving source roots&#39; state to the format this build reads. <code>--all</code> selects every dataset that keeps state; <code>--apply</code> performs the revalidated plan and requires the daemon to be stopped.</td></tr></tbody></table><p><code>dataset adopt</code>, <code>dataset reseed</code>, <code>dataset abort-receive</code>, <code>dataset clean</code>, <code>identity recover</code> and <code>migrate</code> print a readable plan: every action with the object and property it changes, every blocker, every warning, and what was applied, ending with a reminder that a preview changed nothing. Each takes <code>--json</code> to print the same plan as indented JSON instead, which is the form for scripts. The JSON carries the same fields as before these commands had a readable form; text output is for reading and may change between releases.</p><p><code>dataset clean --all</code> cannot be combined with dataset arguments. Named datasets are exact unless <code>--recursive</code> is supplied. Snapshot destruction is never implied by selecting a scope.</p><p><code>dataset clean --forget-target TARGET</code> narrows the clean to one target&#39;s state on each named source root and does not check the target: its recovery proofs, the holds and bookmarks they record, its binding and its suspension marker. <code>TARGET</code> is a configured remote&#39;s name, a local destination root, or a target ID, which is how a remote no longer configured is named; a clean blocked on it reports the ID. Repeat the flag to forget more than one target. It cannot be combined with <code>--recursive</code>, <code>--all</code> or <code>--destroy-owned-snapshots</code>, and the preview is blocked when a named root keeps no state for the target.</p><h2 id="pairing" tabindex="-1">Pairing <a class="header-anchor" href="#pairing" aria-label="Permalink to &quot;Pairing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Options and arguments</th></tr></thead><tbody><tr><td><code>boomerangz pairing create</code></td><td><code>--listener NAME</code>, repeatable <code>--scope VALUE</code>, <code>--expires-in DURATION</code>, and paired <code>--client-cert PATH</code>/<code>--client-key PATH</code>.</td></tr><tr><td><code>boomerangz pairing import NAME BUNDLE</code></td><td>Store a received bundle under a local credential name.</td></tr><tr><td><code>boomerangz pairing list</code></td><td>List credentials issued or imported by this installation.</td></tr><tr><td><code>boomerangz pairing revoke ID</code></td><td>Revoke one issued pairing.</td></tr></tbody></table><p>Allowed scope values are <code>status</code>, <code>trigger</code>, <code>replicate</code>, <code>prune</code>, and <code>admin</code>. The default is <code>status</code>. An expiry of <code>0s</code> means no expiry. <code>--client-cert</code> and <code>--client-key</code> must be supplied together.</p><h2 id="restricted-ssh-command" tabindex="-1">Restricted SSH command <a class="header-anchor" href="#restricted-ssh-command" aria-label="Permalink to &quot;Restricted SSH command&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>boomerangz ssh-shell</span></span></code></pre></div><p>This command serves a restricted receiving endpoint over standard input and output. The packaged <code>/usr/lib/boomerangz/boomerangz-shell</code> login shell invokes it and ignores SSH command arguments. Destination roots are supplied through the replication API and checked against <code>ssh_shell.replication_roots</code>; there is no root command-line option. Administrators do not normally invoke this hidden command directly.</p>',20)])])}const b=t(r,[["render",n]]);export{p as __pageData,b as default};
